// Small, bounded grade and attendance pages prevent oversized DOM trees on Android.
const PAGE_SIZE = 24, pageState={students:0,marks:0,attendance:0,grades:0,events:0};
function pageRows(items,area){
 const pages=Math.max(1,Math.ceil(items.length/PAGE_SIZE));
 pageState[area]=Math.min(Math.max(0,pageState[area]||0),pages-1);
 const page=pageState[area],first=page*PAGE_SIZE;
 return {items:items.slice(first,first+PAGE_SIZE),footer:pages===1?'':`<nav class="page-controls" aria-label="صفحات ${area}"><button class="btn small" data-action="turn-page" data-scope="${area}" data-index="${page-1}" ${page<=0?'disabled':''}>السابق</button><span>صفحة ${page+1} من ${pages} · ${items.length} سجل</span><button class="btn small" data-action="turn-page" data-scope="${area}" data-index="${page+1}" ${page>=pages-1?'disabled':''}>التالي</button></nav>`};
}
