function status(text,kind=''){const el=$('cloudStatus');if(el){el.textContent=text;el.dataset.kind=kind;}}
function setCloudBanner(message='',blocked=false){const el=$('cloudBanner');if(!el)return;el.hidden=!message;el.querySelector('[data-cloud-message]').textContent=message;el.dataset.blocked=String(blocked);document.body.classList.toggle('sync-conflict',blocked);}
function persist(){
 if(!authenticated||cloudBlocked){status('تعذر الحفظ','error');return false;}
 db.updated=new Date().toISOString();cloudDirty=true;status('تغييرات غير محفوظة','pending');
 clearTimeout(cloudTimer);cloudTimer=setTimeout(syncNow,650);return true;
}
function persistSoon(){persist()}
function flushPending(){clearTimeout(cloudTimer);cloudTimer=null;if(cloudDirty&&!cloudBusy)void syncNow()}
async function syncNow(){
 clearTimeout(cloudTimer);cloudTimer=null;
 if(!authenticated||cloudBusy||cloudBlocked||!cloudDirty)return;
 if(!navigator.onLine){document.body.classList.add('cloud-paused');status('بانتظار الاتصال','error');setCloudBanner('انقطع الاتصال. التعديلات الموجودة الآن في الذاكرة فقط؛ لا تغلق التطبيق قبل مزامنتها. نزّل نسخة JSON إذا تعذر الاتصال.');return;}
 cloudBusy=true;cloudDirty=false;const gen=accountGeneration,uid=cloud.user?.id,snapshot=clone(db);
 status('جارٍ الحفظ…','pending');
 try{
  const revision=await cloud.saveWorkspace(snapshot,cloudRevision);
  if(gen!==accountGeneration||uid!==cloud.user?.id)return;
  cloudRevision=revision;
  if(!cloudDirty){document.body.classList.remove('cloud-paused');status('محفوظ سحابياً','ok');setCloudBanner();}
 }catch(e){
  if(gen!==accountGeneration)return;
  cloudDirty=true;document.body.classList.add('cloud-paused');status('لم تُحفظ التغييرات','error');
  if(e.kind==='conflict'){
   cloudBlocked=true;
   setCloudBanner('تعارض مزامنة: توجد تغييرات أحدث من جهاز آخر. نزّل نسخة JSON قبل تحديث البيانات من السحابة. لن نستبدل أياً من النسختين تلقائياً.',true);
  }else setCloudBanner('تعذر حفظ التغييرات في Supabase: '+e.message+' — حاول مجدداً أو نزّل نسخة JSON.');
 }finally{
  if(gen===accountGeneration){cloudBusy=false;if(cloudDirty&&!cloudBlocked&&navigator.onLine)cloudTimer=setTimeout(syncNow,3000)}
 }
}
window.addEventListener('pagehide',flushPending);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushPending()});
