window.addEventListener('offline',()=>{if(authenticated){document.body.classList.add('cloud-paused');status('لا يوجد اتصال','error');setCloudBanner('الاتصال منقطع؛ أوقفت التحرير حتى لا تُفقد الدرجات. استعد الشبكة ثم أعد المحاولة أو نزّل نسخة JSON.');}});
