function options(array,selected,placeholder){return (placeholder?`<option value="">${esc(placeholder)}</option>`:'')+array.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}
function cfgSel(name,items,value){return `<select data-draft="${name}">${items.map(x=>`<option value="${x[0]}" ${String(x[0])===String(value)?'selected':''}>${x[1]}</option>`).join('')}</select>`}
function note(msg,kind='info'){return `<div class="notice ${kind}">${msg}</div>`}
function empty(t,more=''){return `<div class="empty"><span class="big">✧</span><strong>${esc(t)}</strong><div class="hint">${esc(more)}</div></div>`}
