function selectedPeriod(){const arr=C()?.periods||[];if(!arr.some(p=>p.id===periodId))periodId=arr[0]?.id||null;return periodId}
function selectedAssessment(){let a=db.assessments.find(x=>x.id===assessmentId&&x.classId===active);if(!a)assessmentId=db.assessments.find(x=>x.classId===active)?.id||null;return db.assessments.find(x=>x.id===assessmentId)}
function titleFor(){return {dashboard:'نظرة عامة',students:'الطلبة والشعب',assessments:'الاختبارات والأنشطة',attendance:'المواظبة والغياب',grades:'كشوف النتائج',lessons:'دفتر التحضير',lessonEditor:lessonEdit?'تعديل التحضير':'تحضير درس جديد',calendar:'التقويم المدرسي',settings:'معايير التقييم',welcome:'ابدأ بإعداد مساحة عملك',import:'استيراد أسماء الطلبة',more:'كل أدوات إعداد'}[route]||'إعداد'}
function render(){if(!cls()&&!['welcome','import'].includes(route))route='welcome';$('pageTitle').textContent=titleFor();const select=$('globalClass'),selectHtml=options(db.classes,active,'لا توجد شعبة');if(select.innerHTML!==selectHtml)select.innerHTML=selectHtml;$('globalClass').disabled=!db.classes.length;document.getElementById('desktopNav').innerHTML=NAV.map(([id,i,name])=>`<button data-nav="${id}" class="${route===id?'active':''}"><span class="nav-icon">${i}</span>${name}</button>`).join('');$('mobileNav').innerHTML=MOBILE_NAV.map(([id,i,name])=>`<button type="button" aria-label="${name}" aria-current="${route===id?'page':'false'}" data-nav="${id}" class="${route===id?'active':''}"><span class="nav-icon" aria-hidden="true">${i}</span><span>${name}</span></button>`).join('');$('content').innerHTML=({welcome,dashboard,students,assessments,attendance,grades,lessons,lessonEditor,calendar,settings,import:importPage,more}[route]||dashboard)();document.querySelectorAll('.table-wrap').forEach(t=>{t.tabIndex=0;t.setAttribute('role','region');t.setAttribute('aria-label','جدول بيانات قابل للتمرير أفقياً');});if(document.body?.dataset)document.body.dataset.route=route;}
