function dashboard(){const c=cls(),st=studentsFor(db,active),ev=db.assessments.filter(x=>x.classId===active),complete=st.map(x=>termScore(db,c,x.id)).filter(x=>x!==null),studentIds=new Set(st.map(s=>s.id)),attKeys=Object.keys(db.attendance).filter(k=>studentIds.has(k.split('|')[0])),avg=complete.length?(complete.reduce((s,x)=>s+x,0)/complete.length).toFixed(1):'—';const recent=ev.slice().sort((a,b)=>(b.created||'').localeCompare(a.created||'')).slice(0,5);
return `<div class="hero"><span class="tag">إعداد · ${esc(c.subject||'نظام المدرس')} · ${esc(c.year||'السنة الحالية')}</span><h2>التحضير والدرجات والغياب، في نظام واحد.</h2><p>قواعد التقييم تخص شعبة «${esc(c.name)}». تغيير العلامة أو الغياب ينعكس في النتائج دون نسخ الأرقام بين الشاشات.</p><div class="button-row"><button class="btn gold" data-nav="settings">تخصيص المعايير ←</button><button class="btn" data-nav="assessments">إضافة اختبار</button><button class="btn" data-action="install-app">تثبيت التطبيق</button></div></div>${c.config.template?`<div class="distribution"><div class="dist-intro"><span>قالب التوزيع المعتمد لهذه الشعبة</span><strong>النشاط والامتحان الشهري</strong><small>قابلان للتعديل من الإعدادات، ولا يمثلان سياسة موحدة لجميع المواد.</small></div><div class="dist-piece activity"><small>النشاط</small><b>${c.config.categories.filter(x=>x.group==='activity').reduce((z,x)=>z+(+x.max),0)} درجة</b></div><div class="dist-piece monthly"><small>الامتحان الشهري</small><b>${c.config.categories.filter(x=>x.group==='monthly').reduce((z,x)=>z+(+x.max),0)} درجة</b></div></div>`:''}<div class="grid cols4">${metric('الطلبة',st.length,'♙')}${metric('التقييمات',ev.length,'▤')}${metric('جلسات المواظبة',new Set(attKeys.map(k=>k.split('|')[2])).size,'▣')}${metric('متوسط النتائج المكتملة',avg,'▥',`من ${complete.length} نتيجة`)}</div><div class="grid cols2" style="margin-top:18px"><div class="panel"><h3>دورة العمل</h3><div class="list"><div class="list-item"><div><strong>1. ضبط المعايير</strong><small>أنشئ الفترات وعناصر التقييم وطريقة التجميع بنفسك</small></div><button class="btn small" data-nav="settings">الإعدادات</button></div><div class="list-item"><div><strong>2. إضافة الطلبة</strong><small>يدوياً أو من ملف Excel مع معاينة واختيار العمود</small></div><button class="btn small" data-nav="students">الطلبة</button></div><div class="list-item"><div><strong>3. إنشاء اختبارات وسجل غياب</strong><small>عدد غير محدود من الاختبارات في كل فترة</small></div><button class="btn small" data-nav="assessments">الاختبارات</button></div><div class="list-item"><div><strong>4. تقارير مترابطة</strong><small>تفاصيل الدرجات ومراجعة النتائج غير المكتملة</small></div><button class="btn small" data-nav="grades">التقارير</button></div></div></div><div class="panel"><h3>أحدث التقييمات</h3>${recent.length?`<div class="list">${recent.map(a=>`<div class="list-item"><div><strong>${esc(a.title)}</strong><small>${esc(c.config.periods.find(p=>p.id===a.periodId)?.name||'')} · الحد الأقصى ${a.max} · ${esc(a.date)}</small></div><button class="btn small" data-action="open-assessment" data-id="${a.id}">الدرجات</button></div>`).join('')}</div>`:empty('لا توجد اختبارات بعد','اذهب إلى قسم الاختبارات لإنشاء تقييم جديد.')}</div></div>`;}
function students(){const all=studentsFor(db,active).filter(s=>s.name.includes(studentFilter)).sort((a,b)=>a.name.localeCompare(b.name,'ar'));const page=pageRows(all,'students'),st=page.items;return `<div class="page-head"><div><h2>قائمة الطلبة</h2><p class="hint">ترتبط جميع سجلات الاختبارات والغياب بالمعرّف الداخلي للطالب، لا بترتيبه في الجدول.</p></div><div class="button-row"><button class="btn" data-nav="import">⇧ استيراد Excel</button><button class="btn primary" data-action="prompt-student">＋ طالب جديد</button><button class="btn" data-action="new-class">＋ شعبة</button></div></div><div class="panel"><div class="searchbar"><input class="search" data-filter="students" placeholder="ابحث عن اسم طالب..." value="${esc(studentFilter)}"></div>${st.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>الاسم الكامل</th><th>الفترات المكتملة</th><th>نتيجة الفترات</th><th>النتيجة النهائية</th><th>الإجراءات</th></tr></thead><tbody>${st.map((s,i)=>`<tr><td>${i+1}</td><td>${esc(s.name)}</td><td>${C().periods.filter(p=>periodScore(db,cls(),s.id,p.id).value!==null).length} / ${C().periods.length}</td><td>${scoreText(termScore(db,cls(),s.id))}</td><td>${scoreText(annualScore(db,cls(),s.id))}</td><td><button class="btn small" data-action="rename-student" data-id="${s.id}">تعديل</button> <button class="btn danger small" data-action="delete-student" data-id="${s.id}">حذف</button></td></tr>`).join('')}</tbody></table></div>`:empty('لا توجد أسماء مطابقة','يمكن إدخال الطلبة يدوياً أو استيراد ملف XLSX أو CSV.')}${page.footer}</div>`}
function scoreText(x){return x===null?'<span class="badge warn">غير مكتمل</span>':`<span class="${x>=C().pass?'score-good':'score-bad'}">${esc(x)} / ${esc(C().scale)}</span>`}
function assessmentForm(){return `<form id="assessmentForm" class="panel"><h3>إنشاء تقييم جديد</h3><p class="hint">أدخل أي عدد من الاختبارات. حد كل اختبار مستقل عن وزن عنصر التقييم.</p><div class="fields">${field('عنوان الاختبار أو النشاط','title','','text','required maxlength="120" placeholder="مثال: اختبار الوحدة الأولى"')}<label class="field"><span>الفترة</span><select name="periodId">${options(C().periods,selectedPeriod())}</select></label><label class="field"><span>عنصر التقييم</span><select name="categoryId">${options(C().categories.filter(x=>!(C().attendance.mode==='category'&&x.id===C().attendance.categoryId)),C().categories[0]?.id)}</select></label><label class="field"><span>تصنيف السجل عند احتساب العملي (يُستخدم في بطاقة التمارين)</span><select name="role"><option value="regular">نشاط أو اختبار عادي</option><option value="practice">تمارين عملية خلال الشهر</option><option value="practical_exam">الامتحان العملي الشهري</option></select></label>${field('الدرجة القصوى لهذا الاختبار','max','10','number','min="0.01" max="10000" step="any" required')}${field('التاريخ','date',now(),'date')}</div><div class="action-strip"><button class="btn primary" type="submit">＋ إنشاء الاختبار</button></div></form>`}
function assessments(){const ev=db.assessments.filter(x=>x.classId===active).sort((a,b)=>(a.date||'').localeCompare(b.date||''));selectedAssessment();const a=selectedAssessment();const marksPage=pageRows(studentsFor(db,active).sort((x,y)=>x.name.localeCompare(y.name,'ar')),'marks'),st=marksPage.items,eventsPage=pageRows(ev,'events');return `<div class="page-head"><div><h2>الاختبارات والأنشطة</h2><p class="hint">الفترة إطار زمني. سجّل الامتحانات اليومية ضمن عنصرها من 4 درجات عند اختيار قالب الوثيقة، وسجّل النظري والعملي في عناصرهما المستقلة.</p></div><button class="btn" data-nav="settings">⚙ ضبط طريقة التجميع</button></div>${assessmentForm()}<div class="action-strip"><button class="btn small gold" data-action="initialize-activity">＋ تجهيز سجل نشاط الفترة (الحضور والسلوك والمشاركة والمستلزمات)</button></div><div class="grid cols2" style="margin-top:16px"><div class="panel"><h3>قائمة التقييمات (${ev.length})</h3>${ev.length?`<div class="list">${eventsPage.items.map(e=>`<div class="list-item" style="${e.id===assessmentId?'border-color:#7b86dd;background:#fafaff':''}"><div><strong>${esc(e.title)}</strong><small>${esc(C().periods.find(p=>p.id===e.periodId)?.name)} · ${esc(C().categories.find(cat=>cat.id===e.categoryId)?.name)} · ${e.max} درجة · ${esc(e.role==='practice'?'تمارين عملية':e.role==='practical_exam'?'امتحان عملي':'تقييم')} · ${esc(e.date)}</small></div><div class="button-row"><button class="btn small ${e.id===assessmentId?'primary':''}" data-action="open-assessment" data-id="${e.id}">إدخال</button><button class="btn small" data-action="change-event-max" data-id="${e.id}">الحد</button><button class="btn danger small" data-action="delete-event" data-id="${e.id}">حذف</button></div></div>`).join('')}</div>${eventsPage.footer}`:empty('لم تُنشأ اختبارات بعد')}</div><div class="panel"><h3>إجمالي درجات الاختبارات</h3>${C().periods.map(p=>`<div class="mini-card"><b>${esc(p.name)}</b><div class="hint">${C().categories.map(cat=>`${esc(cat.name)}: ${eventsFor(db,active,p.id,cat.id).length} اختبار`).join(' · ')}</div></div>`).join('')}${note('طريقة التجميع محددة لكل عنصر في الإعدادات: مجموع الدرجات المعيارية، متوسط النسب، أعلى نسبة، آخر اختبار، مجموع خام بسقف، أو أفضل N يختاره المدرس.')}</div></div>${a?`<div class="panel" style="margin-top:16px"><div class="page-head"><div><h3>كشف الدرجات: ${esc(a.title)}</h3><p class="hint">كل خانة تعرض حدها الأقصى. الخلية الفارغة ليست صفراً؛ الصفر المكتوب يُحسب صفراً.</p></div><span class="badge">من ${a.max} درجة</span></div>${st.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>اسم الطالب</th><th>الدرجة / الحد</th><th>الحالة</th></tr></thead><tbody>${st.map(s=>{const value=db.marks[a.id]?.[s.id];return `<tr><td>${esc(s.name)}</td><td><div class="score-cell"><input data-mark="${a.id}|${s.id}" aria-label="درجة ${esc(s.name)} من ${a.max}" type="number" min="0" max="${a.max}" step="any" value="${value??''}" placeholder="—"><small>/ ${a.max}</small></div></td><td><span class="${value==null?'badge warn':'badge ok'}">${value==null?'لم تُدخل':'محفوظة'}</span></td></tr>`}).join('')}</tbody></table></div>${marksPage.footer}`:empty('أضف الطلبة أولاً','ستظهر حقول الدرجات بمجرد إنشاء الطلاب.')}</div>`:''}`;}
function attendance(){selectedPeriod();const page=pageRows(studentsFor(db,active).sort((a,b)=>a.name.localeCompare(b.name,'ar')),'attendance'),st=page.items;const date=window.__attDate||now();const statuses=[['','— لم يُرصد —'],['present','حاضر'],['absent','غائب'],['excused','بعذر'],['late','متأخر']];const pid=selectedPeriod();return `<div class="page-head"><div><h2>سجل الحضور والغياب</h2><p class="hint">سجل حسب تاريخ الحصة والفترة، مع تحديث التقارير مباشرةً. لا يُفرض خصم إلا من الإعدادات.</p></div><button class="btn" data-nav="settings">سياسة الغياب</button></div><div class="panel"><div class="fields"><label class="field"><span>الفترة</span><select id="attendancePeriod">${options(C().periods,pid)}</select></label><label class="field"><span>تاريخ الحصة</span><input type="date" id="attendanceDate" value="${esc(date)}"></label></div><div class="action-strip"><button class="btn" data-action="mark-all-present">تحديد غير المرصودين حاضرين</button><span class="badge">الغياب: ${C().attendance.mode==='none'?'للمتابعة فقط':C().attendance.mode==='deduct'?'خصم من النتيجة':'ضمن عنصر المواظبة'}</span></div>${st.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>اسم الطالب</th><th>حالة هذه الحصة</th><th>غياب الفترة</th><th>التأخر</th><th>بعذر</th></tr></thead><tbody>${st.map(s=>{const key=`${s.id}|${pid}|${date}`,v=db.attendance[key]||'',sum=attendanceStats(db,s.id,pid);return `<tr><td>${esc(s.name)}</td><td><select data-att="${s.id}" aria-label="مواظبة ${esc(s.name)}">${statuses.map(([id,label])=>`<option value="${id}" ${v===id?'selected':''}>${label}</option>`).join('')}</select></td><td>${sum.absent}</td><td>${sum.late}</td><td>${sum.excused}</td></tr>`}).join('')}</tbody></table></div>${page.footer}`:empty('لا يوجد طلبة لهذه الشعبة')}</div>`}
function stageEditor(){const stages=C().stages||[],st=pageRows(studentsFor(db,active).filter(s=>s.name.includes(gradeFilter)).sort((a,b)=>a.name.localeCompare(b.name,'ar')),'grades').items;
 if(!stages.length)return note('لم تُنشأ امتحانات مستقلة لنصف السنة أو نهاية السنة. أضفها من الإعدادات إذا كانت مطلوبة للمادة.', 'info');
 return `<div class="panel settings-section" id="stageExamResults"><div class="page-head"><div><h3>امتحانات نصف السنة ونهاية السنة — مستقلة عن الشهري</h3><p class="hint">يظهر النظري والتطبيقي بحسب قالب هذه الشعبة. تُجمع المكونات إلى 100 عندما تكتمل، ولا تُحتسب سنوياً تلقائياً إلا باختيارها في معادلة النتيجة السنوية.</p></div><button class="btn small" data-nav="settings">تخصيص الامتحانات</button></div>${stages.map(stage=>`<div class="mini-card"><h3>${esc(stage.name)} <span class="badge">من ${stage.scale}</span></h3><div class="table-wrap"><table class="data-table"><thead><tr><th>الطالب</th>${stage.components.map(comp=>`<th>${esc(comp.name)} / ${comp.max}</th>`).join('')}<th>مجموع الامتحان</th></tr></thead><tbody>${st.map(student=>{const res=stageScore(db,cls(),student.id,stage.id);return `<tr><td>${esc(student.name)}</td>${stage.components.map(comp=>`<td><div class="score-cell"><input data-stage-mark="${student.id}|${stage.id}|${comp.id}" type="number" min="0" max="${comp.max}" step="any" value="${db.stageMarks?.[student.id]?.[stage.id]?.[comp.id]??''}" placeholder="—" aria-label="${esc(comp.name)} ${esc(student.name)}"><small>/ ${comp.max}</small></div></td>`).join('')}<td>${res.value===null?'<span class="badge warn">غير مكتمل</span>':`<strong class="score-good">${res.value} / ${stage.scale}</strong>`}</td></tr>`}).join('')}</tbody></table></div></div>`).join('')}</div>`;
}
function grades(){selectedPeriod();const all=studentsFor(db,active).sort((a,b)=>a.name.localeCompare(b.name,'ar')).filter(s=>s.name.includes(gradeFilter)),page=pageRows(all,'grades'),st=page.items;let pid=selectedPeriod(),p=C().periods.find(p=>p.id===pid);const ev=db.assessments.filter(e=>e.classId===active&&e.periodId===pid);const headers=ev.map(a=>`<th>${esc(a.title)}<div class="table-note">من ${a.max}</div></th>`).join('');const complete=st.filter(s=>termScore(db,cls(),s.id)!==null),avg=complete.length?rounded(complete.reduce((s,x)=>s+termScore(db,cls(),x.id),0)/complete.length,'two'):'—';
return `<div class="page-head"><div><h2>نتائج مترابطة وقابلة للتدقيق</h2><p class="hint">لا توجد معادلة مخفية لاختيار اختبارين. يُحتسب كل عنصر وفق سياسة المدرس، وتظهر القيم الناقصة صراحة.</p></div><div class="button-row"><button class="btn" data-action="export-grades">⇩ تصدير CSV</button><button class="btn" data-action="print-page">▤ طباعة / PDF</button></div></div><div class="grid cols3" style="margin-bottom:18px">${metric('الطلبة في هذه الصفحة',st.length,'♙',`من ${all.length}`)}${metric('المكتملون بهذه الصفحة',complete.length,'✓')}${metric('متوسط النتائج بهذه الصفحة',avg,'▥')}</div><div class="seg-tabs">${C().periods.map(x=>`<button class="${x.id===pid?'active':''}" data-action="choose-period" data-id="${x.id}">${esc(x.name)}</button>`).join('')}</div><div class="panel"><div class="searchbar"><input class="search" data-filter="grades" value="${esc(gradeFilter)}" placeholder="البحث عن طالب في التقرير"></div><h3>تفاصيل الفترة: ${esc(p?.name||'')}</h3><p class="hint">الاختبارات اليومية جزء من النشاط وليست مضافة فوقه. تظهر الدرجة الخام، ثم نتيجة العنصر، ثم مجاميع النشاط والامتحان الشهري على سلم ${C().scale}.</p>${st.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الطالب</th>${headers}${C().categories.map(cat=>`<th>${esc(cat.name)}<div class="table-note">من ${cat.max}</div></th>`).join('')}${['activity','monthly'].filter(group=>C().categories.some(x=>(x.group||'general')===group)).map(group=>`<th>${group==='activity'?'النشاط':'الامتحان الشهري'}<div class="table-note">من ${C().categories.filter(x=>x.group===group).reduce((t,x)=>t+(+x.max),0)}</div></th>`).join('')}<th>الغياب</th><th>الفترة / ${C().scale}</th></tr></thead><tbody>${st.map(s=>{const result=periodScore(db,cls(),s.id,pid);return `<tr><td>${esc(s.name)}</td>${ev.map(a=>`<td>${db.marks[a.id]?.[s.id]??'<span class="hint">—</span>'} <span class="table-note">/ ${a.max}</span></td>`).join('')}${C().categories.map(cat=>{const calc=categoryScore(db,cls(),s.id,pid,cat);return `<td title="${esc(methodLabel(cat))}">${calc.value===null?'<span class="badge warn">ناقص</span>':`<span class="score-good">${rounded(calc.value,'two')}</span>`}</td>`}).join('')}${['activity','monthly'].filter(group=>C().categories.some(x=>(x.group||'general')===group)).map(group=>`<td>${groupScore(db,cls(),s.id,pid,group).value??'—'}</td>`).join('')}<td>${result.attendance?.absent??attendanceStats(db,s.id,pid).absent}</td><td>${scoreText(result.value)} ${result.penalty?`<span class="warn-text">−${result.penalty}</span>`:''}</td></tr>`}).join('')}</tbody></table></div>`:empty('لا توجد سجلات')}</div><div class="panel" style="margin-top:17px"><h3>ملخص الفترات والنتيجة النهائية</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>الطالب</th>${C().periods.map(p=>`<th>${esc(p.name)} <span class="table-note">وزن ${p.weight}</span></th>`).join('')}<th>معدل الفترات</th>${C().annual.filter(x=>x.source==='manual').map(x=>`<th>${esc(x.name)} / ${C().scale}</th>`).join('')}<th>النتيجة النهائية</th><th>التفاصيل</th></tr></thead><tbody>${st.map(s=>`<tr><td>${esc(s.name)}</td>${C().periods.map(p=>`<td>${periodScore(db,cls(),s.id,p.id).value??'—'}</td>`).join('')}<td>${scoreText(termScore(db,cls(),s.id))}</td>${C().annual.filter(x=>x.source==='manual').map(x=>`<td><div class="score-cell"><input type="number" data-manual="${s.id}|${x.id}" min="0" max="${C().scale}" step="any" value="${db.manual[s.id]?.[x.id]??''}" placeholder="—" aria-label="${esc(x.name)} ${esc(s.name)}"><small>/${C().scale}</small></div></td>`).join('')}<td>${scoreText(annualScore(db,cls(),s.id))}</td><td><button class="btn small" data-action="explain-student" data-id="${s.id}">كيف حُسبت؟</button></td></tr>`).join('')}</tbody></table></div>${page.footer}</div>${stageEditor()}${note(`سياسة البيانات الناقصة: <strong>${{incomplete:'لا يظهر المعدل حتى تكتمل القيم المطلوبة',available:'يحسب من المدخلات المتاحة فقط',zero:'يُحسب غير المدخل صفراً'}[C().missing]}</strong>. سياسات التقريب والأوزان قابلة للتغيير في الإعدادات.`)}`}
function methodLabel(cat){return {weighted:'جميع الاختبارات مرجّحة بحدودها القصوى',average:'متوسط نسب جميع الاختبارات بالتساوي',sum:'مجموع الدرجات الخام حتى سقف العنصر',highest:'أعلى نسبة اختبار واحد',last:'آخر اختبار زمنياً',best:`أفضل ${cat.bestN} اختبارات حسب النسبة`,practical_pair:'بطاقة التمارين: متوسط نسبة التمارين ونسبة الامتحان العملي ثم تحويلها لوزن العنصر؛ وعند غياب بطاقة التمارين يُحسب الامتحان العملي وحده'}[cat.method]||''}
function lessons(){const ls=db.lessons.filter(x=>x.classId===active).sort((a,b)=>b.date.localeCompare(a.date)),st=ls.length;return `<div class="page-head"><div><h2>دفتر تحضير الدروس</h2><p class="hint">تحضيرات الشعبة الحالية، منفصلة عن بيانات السنة القديمة.</p></div><button class="btn primary" data-action="add-lesson">＋ إضافة تحضير</button></div><div class="grid cols3">${metric('التحضيرات',st,'✎')}${metric('تحضير هذا الشهر',ls.filter(x=>x.date.slice(0,7)===now().slice(0,7)).length,'▦')}${metric('السنة الدراسية',esc(cls().year||'—'),'✧')}</div><div class="panel" style="margin-top:18px"><h3>التحضيرات المسجلة</h3>${ls.length?`<div class="list">${ls.map(l=>`<div class="list-item"><div><strong>${esc(l.title)}</strong><small>${esc(l.date)} · ${esc(l.type)} · ${esc(l.subject)}</small></div><div class="button-row"><button class="btn small" data-action="edit-lesson" data-id="${l.id}">تحرير</button><button class="btn small" data-action="print-lesson" data-id="${l.id}">طباعة</button><button class="btn danger small" data-action="delete-lesson" data-id="${l.id}">حذف</button></div></div>`).join('')}</div>`:empty('لا توجد تحضيرات بعد','ابدأ بإضافة أول تحضير للدرس.')}</div>`}
function lessonEditor(){const l=db.lessons.find(x=>x.id===lessonEdit)||{date:now(),title:'',type:'درس',subject:cls()?.subject||'',grade:cls()?.name||'',body:'',goals:'',homework:'',evaluation:''};return `<div class="page-head"><div><h2>${lessonEdit?'تحرير تحضير':'تحضير درس جديد'}</h2><p class="hint">الإملاء الصوتي متاح حسب دعم المتصفح وأذونات الميكروفون، وقد يحتاج إلى شبكة.</p></div><button class="btn" data-nav="lessons">عودة إلى الدفتر</button></div><form id="lessonForm" class="panel"><div class="fields">${field('عنوان الدرس','title',l.title,'text','required maxlength="180"')}${field('تاريخ التدريس','date',l.date,'date','required')}<label class="field"><span>نوع التحضير</span><select name="type">${['درس','مراجعة','امتحان','تطبيق','نشاط'].map(x=>`<option ${l.type===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('المادة','subject',l.subject)}<label class="field wide"><span>محتوى التحضير</span><textarea name="body" id="lessonBody" rows="7">${esc(l.body)}</textarea></label><div class="field wide"><div class="button-row"><button class="btn" type="button" data-action="dictate">🎙 إملاء صوتي</button><button class="btn" type="button" data-action="lesson-template">✧ إدراج هيكل تحضير مساعد</button></div><small id="voiceInfo" class="hint">قالب التحضير المقترح محلي، وليس توليداً آلياً معتمداً على نموذج لغوي.</small></div><label class="field wide"><span>الأهداف التعليمية</span><textarea name="goals" rows="3">${esc(l.goals)}</textarea></label><label class="field wide"><span>التقويم وأسئلة التحقق</span><textarea name="evaluation" rows="3">${esc(l.evaluation)}</textarea></label><label class="field wide"><span>الواجبات</span><textarea name="homework" rows="3">${esc(l.homework)}</textarea></label></div><div class="action-strip"><button class="btn primary" type="submit">حفظ التحضير</button></div></form>`}
function calendar(){const m=calendarMonth,y=m.getFullYear(),month=m.getMonth(),first=(new Date(y,month,1).getDay()+1)%7,days=new Date(y,month+1,0).getDate();const ls=db.lessons.filter(l=>l.classId===active),as=db.assessments.filter(a=>a.classId===active);const wd=['السبت','الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة'];let items=[];for(let i=0;i<first+days;i++){if(i<first){items.push(`<div class="cal-day dim"></div>`);continue}let d=i-first+1,date=`${y}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,l=ls.filter(x=>x.date===date),a=as.filter(x=>x.date===date);items.push(`<button class="cal-day ${date===now()?'today':''}" data-action="calendar-date" data-id="${date}"><b>${d}</b>${l.slice(0,1).map(x=>`<small>✎ ${esc(x.title)}</small>`).join('')}${a.slice(0,1).map(x=>`<small>▤ ${esc(x.title)}</small>`).join('')}${l.length+a.length>2?`<small>+${l.length+a.length-2}</small>`:''}</button>`)}return `<div class="page-head"><div><h2>التقويم الدراسي</h2><p class="hint">يجمع مواعيد الدروس والاختبارات معاً.</p></div><div class="button-row"><button class="btn" data-action="shift-month" data-id="-1">السابق</button><strong>${new Intl.DateTimeFormat('ar-IQ',{month:'long',year:'numeric'}).format(m)}</strong><button class="btn" data-action="shift-month" data-id="1">التالي</button></div></div><div class="panel"><div class="cal-grid">${wd.map(x=>`<div class="cal-head">${x}</div>`).join('')}${items.join('')}</div></div>`}
function settings(){if(!configDraft)configDraft=clone(C());const c=configDraft;const modeOptions=[['weighted','كل الاختبارات، مرجحة بالدرجة القصوى'],['average','متوسط نسب جميع الاختبارات'],['sum','مجموع الدرجات الخام بسقف العنصر'],['highest','أعلى اختبار واحد'],['last','آخر اختبار زمنياً'],['best','أفضل عدد N (تحدده أنت)'],['practical_pair','بطاقة التمارين + الامتحان العملي (50% لكل جانب)']];let referencedPeriod=id=>db.assessments.some(e=>e.classId===active&&e.periodId===id)||Object.keys(db.attendance).some(k=>studentsFor(db,active).some(s=>k.startsWith(s.id+'|'+id+'|'))),referencedCategory=id=>db.assessments.some(e=>e.classId===active&&e.categoryId===id);
return `<div class="page-head"><div><h2>استوديو إعداد المعايير</h2><p class="hint">أنشئ منطق التقييم أولاً؛ تتغير الحقول والكشوف آلياً، بلا عدد امتحانات محدد مسبقاً.</p></div><div class="button-row"><button class="btn" data-action="reset-draft">التراجع عن التعديلات</button><button class="btn primary" data-action="save-config">حفظ واعتماد المعايير</button></div></div>${note('المعايير التالية تخص هذه الشعبة فقط. قوالب توزيع الدرجات مستندة إلى الصورة المرجعية لكنها اختيارية؛ اختر ما ينطبق من المرحلة والفرع وفق التعليمات المعتمدة لديك. يمكن إضافة فترات وعناصر وأنواع حساب دون تحديد أعداد ثابتة. لن تُحذف درجات مرتبطة بعناصر مشغولة عند تغيير الإعدادات.')}
<div class="panel settings-section"><h3>بيانات المدرس والشعبة</h3><form id="profileForm"><div class="fields">${field('اسم المدرس','teacher',db.profile.teacher||'')}${field('اسم المؤسسة التعليمية','institution',db.profile.institution||'')}${field('السنة الدراسية','year',cls().year||'')}${field('اسم المادة','subject',cls().subject||'')}</div><div class="action-strip"><button class="btn" type="submit">حفظ بيانات الشعبة</button><button class="btn" type="button" data-action="rename-class">إعادة تسمية الشعبة</button><button class="btn" type="button" data-action="new-class">＋ شعبة جديدة</button><button class="btn danger" type="button" data-action="delete-class" ${db.classes.length===1?'disabled':''}>حذف الشعبة</button></div></form></div>
<div class="panel settings-section"><h3>01 · قواعد عامة</h3><div class="fields"><label class="field"><span>سلم الدرجة النهائي</span><input data-draft="scale" type="number" min="0.1" max="10000" step="any" value="${c.scale}"></label><label class="field"><span>حد النجاح</span><input data-draft="pass" type="number" min="0" max="${c.scale}" step="any" value="${c.pass}"></label><label class="field"><span>تقريب الدرجات</span>${cfgSel('precision',[['integer','عدد صحيح'],['one','منزلة عشرية'],['two','منزلتان عشريتان']],c.precision)}</label><label class="field"><span>الخانات غير المدخلة</span>${cfgSel('missing',[['incomplete','معدل غير مكتمل حتى الإدخال'],['available','احسب المدخل فقط'],['zero','عامل الخانة الناقصة كصفر']],c.missing)}</label></div></div>
<div class="panel settings-section"><div class="page-head"><div><h3>02 · فترات التقييم</h3><p class="hint">الفترة ليست امتحاناً. يمكنك إنشاء فترة أسبوعية أو شهرية أو فصلية، وتعديل وزنها.</p></div><button class="btn primary small" data-action="add-period">＋ إضافة فترة</button></div>${c.periods.map((p,i)=>`<div class="mini-card"><div class="mini-head"><span class="number-step">${i+1}</span><b>فترة تقييم</b><button class="btn danger small" style="margin-right:auto" data-action="remove-period" data-index="${i}" ${c.periods.length===1?'disabled':''} title="${referencedPeriod(p.id)?'يجب أولاً إزالة سجلات الاختبارات والغياب التابعة':''}">حذف</button></div><div class="fields"><label class="field"><span>اسم الفترة</span><input data-draft="periods/${i}/name" value="${esc(p.name)}" maxlength="100"></label><label class="field"><span>وزن الفترة عند حساب معدل الفترات</span><input data-draft="periods/${i}/weight" type="number" min="0" step="any" value="${p.weight}"></label></div></div>`).join('')||empty('لا توجد فترات')}</div>
<div class="panel settings-section"><div class="page-head"><div><h3>03 · عناصر التقييم</h3><p class="hint">الحد هنا هو وزن العنصر في الفترة. داخل كل عنصر أنشئ أي عدد من الاختبارات بحدود مستقلة.</p></div><button class="btn primary small" data-action="add-category">＋ عنصر تقييم</button></div><div class="notice info" style="margin:0 0 12px">مجموع حدود عناصر الفترة: <strong>${c.categories.reduce((t,x)=>t+(Number(x.max)||0),0)}</strong> مقابل سلم التصحيح ${c.scale}. عند اختلافهما يحوّل التطبيق النسبة إلى سلم الدرجة المختار. قوالب الوثيقة مجموعها 100 (نشاط 20 + شهري 80).</div>${c.categories.map((cat,i)=>`<div class="mini-card"><div class="mini-head"><span class="number-step">${i+1}</span><b>${esc(cat.name)}</b><button class="btn danger small" style="margin-right:auto" data-action="remove-category" data-index="${i}" ${c.categories.length===1?'disabled':''}>حذف</button></div><div class="fields"><label class="field"><span>اسم العنصر</span><input data-draft="categories/${i}/name" maxlength="100" value="${esc(cat.name)}"></label><label class="field"><span>الحد الأعلى لوزن العنصر</span><input type="number" data-draft="categories/${i}/max" min="0.1" max="10000" step="any" value="${cat.max}"></label><label class="field"><span>تصنيف العنصر (للعرض والتقارير)</span>${cfgSel(`categories/${i}/group`,[['activity','نشاط شهري'],['monthly','امتحان شهري'],['general','تقييم آخر']],cat.group||'general')}</label><label class="field wide"><span>كيف تُجمع الاختبارات ضمن هذا العنصر؟</span>${cfgSel(`categories/${i}/method`,modeOptions,cat.method)}</label>${cat.method==='best'?`<label class="field"><span>عدد أفضل الاختبارات (N)</span><input type="number" data-draft="categories/${i}/bestN" min="1" max="10000" step="1" value="${cat.bestN}"></label>`:''}</div><p class="hint">${esc(methodLabel(cat))} · الاختبارات الموجودة لهذا العنصر: ${db.assessments.filter(a=>a.classId===active&&a.categoryId===cat.id).length}</p></div>`).join('')}</div>
<div class="panel settings-section"><h3>04 · ارتباط الغياب بالحسابات</h3><div class="fields"><label class="field"><span>السياسة</span>${cfgSel('attendance/mode',[['none','متابعة وإحصاء فقط بلا خصم'],['deduct','خصم من نتيجة الفترة'],['category','عنصر مواظبة محسوب ضمن الدرجة']],c.attendance.mode)}</label><label class="field"><span>قيمة الخصم عن كل غياب</span><input data-draft="attendance/penalty" type="number" min="0" step="any" value="${c.attendance.penalty}"></label><label class="field"><span>الحد الأعلى للخصم في الفترة</span><input data-draft="attendance/cap" type="number" min="0" step="any" value="${c.attendance.cap}"></label><label class="field"><span>معامل التأخر من الغياب (0 إلى 1)</span><input data-draft="attendance/lateFactor" type="number" min="0" max="1" step="any" value="${c.attendance.lateFactor}"></label>${c.attendance.mode==='category'?`<label class="field wide"><span>عنصر المواظبة المعتمد (لن تدخل فيه الاختبارات)</span><select data-draft="attendance/categoryId">${options(c.categories,c.attendance.categoryId,'اختر العنصر')}</select></label>`:''}</div><p class="hint">الوثيقة تمنح الحضور اليومي 4 درجات لكنها لا تحدد قيمة الخصم عن كل غياب. لذلك لا نخصم شيئاً تلقائياً في القالب؛ يمكن للمدرس إدخال درجة الحضور من 4، أو تفعيل عنصر المواظبة وتحديد خصم معتمد بعد تسجيل الحصص، من دون خصم مزدوج.</p></div>
<div class="panel settings-section"><div class="page-head"><div><h3>05 · امتحانات نصف السنة ونهاية السنة</h3><p class="hint">مستقلة عن النشاط والامتحان الشهري. اختر 100 تحريري أو 50 نظري + 50 عملي فقط وفق المرحلة والمادة المنطبقة، ثم عدّل الحدود بنفسك.</p></div><button class="btn primary small" data-action="add-stage">＋ إضافة امتحان مستقل</button></div>
${(c.stages||[]).map((stage,i)=>`<div class="mini-card"><div class="mini-head"><span class="number-step">${i+1}</span><b>${esc(stage.name)}</b><button class="btn danger small" style="margin-right:auto" data-action="remove-stage" data-index="${i}">حذف الامتحان</button></div><div class="fields"><label class="field"><span>اسم الامتحان</span><input data-draft="stages/${i}/name" value="${esc(stage.name)}"></label><label class="field"><span>درجة الامتحان الكلية</span><input type="number" min="1" max="10000" step="any" data-draft="stages/${i}/scale" value="${stage.scale}"></label></div><div class="section-sub">مكونات الامتحان (مجموعها يجب أن يساوي الدرجة الكلية)</div>${stage.components.map((comp,j)=>`<div class="mini-head stage-row"><label class="field"><span>المكوّن</span><input data-draft="stages/${i}/components/${j}/name" value="${esc(comp.name)}"></label><label class="field"><span>حده الأقصى</span><input type="number" min="0.01" max="10000" step="any" data-draft="stages/${i}/components/${j}/max" value="${comp.max}"></label><button class="btn danger small" data-action="remove-stage-part" data-index="${i}" data-part="${j}" ${stage.components.length===1?'disabled':''}>حذف</button></div>`).join('')}<div class="button-row"><button class="btn small" data-action="add-stage-part" data-index="${i}">＋ إضافة مكوّن</button><span class="badge">مجموع المكونات: ${stage.components.reduce((t,x)=>t+(Number(x.max)||0),0)} / ${stage.scale}</span></div></div>`).join('')||empty('لم تُعرّف امتحانات مستقلة')}
</div>
<div class="panel settings-section"><div class="page-head"><div><h3>06 · النتيجة السنوية</h3><p class="hint">مراحل قابلة للإضافة: معدل الفترات، نصف السنة، اختبار نهائي، أو أي مرحلة تدخل يدوياً.</p></div><button class="btn primary small" data-action="add-annual">＋ مرحلة أخرى</button></div>${c.annual.map((a,i)=>`<div class="mini-card"><div class="mini-head"><b>${esc(a.name)}</b><button class="btn danger small" style="margin-right:auto" data-action="remove-annual" data-index="${i}" ${c.annual.length===1?'disabled':''}>حذف</button></div><div class="fields"><label class="field"><span>اسم المرحلة</span><input data-draft="annual/${i}/name" value="${esc(a.name)}" maxlength="100"></label><label class="field"><span>الوزن النسبي</span><input data-draft="annual/${i}/weight" type="number" min="0" step="any" value="${a.weight}"></label><label class="field wide"><span>المصدر</span>${cfgSel(`annual/${i}/source`,[['periods','احتساب معدل الفترات آلياً'],['stage','ربط بامتحان نصف السنة أو نهاية السنة المحسوب'],['manual','إدخال درجة هذه المرحلة من كشف النتائج']],a.source)}</label>${a.source==='stage'?`<label class="field"><span>اختر الامتحان المستقل</span><select data-draft="annual/${i}/stageId">${options(c.stages||[],a.stageId,'اختر الامتحان')}</select></label>`:''}</div></div>`).join('')}</div>
<div class="action-strip"><button class="btn primary" data-action="save-config">✓ حفظ جميع المعايير</button><button class="btn" data-action="copy-config">نسخ إعدادات من شعبة أخرى</button></div><div class="panel settings-section"><h3>النسخ الاحتياطي وإدارة البيانات</h3><p class="hint">تُحفظ البيانات سحابياً بشكل منفصل لكل مدرس. تأكد من ظهور «محفوظ سحابياً»، واحتفظ بنسخة JSON احتياطية دورية.</p><div class="button-row"><button class="btn" data-action="backup">⇩ تنزيل نسخة احتياطية</button><button class="btn" data-action="restore">⇧ استعادة نسخة احتياطية</button><button class="btn" data-action="export-grades">⇩ تصدير كشف Excel-compatible CSV</button></div></div>${note('حماية البيانات: يمنع التطبيق حذف فترة أو عنصر لديه اختبارات مرتبطة به قبل معالجة تلك السجلات. ولن يسمح بتصغير سلم الدرجة إذا كانت لديه درجات مراحل سنوية أعلى من الحد الجديد.')}`;}
function importPage(){if(!importSheets)return `<div class="page-head"><div><h2>استيراد أسماء من Excel</h2><p class="hint">اختر الملف؛ لن تُستورد درجاته أو معلوماته القديمة تلقائياً.</p></div><button class="btn" data-nav="students">عودة</button></div><div class="panel"><h3>استيراد ملف إلى حساب المدرس الحالي</h3>${note('الملفات المدعومة XLSX وXLSM وCSV. لا يتم تشغيل ماكرو Excel. تُقرأ الأسماء داخل الجهاز، ثم تُحفظ السجلات المستوردة إلى مساحتك الخاصة في Supabase بعد تأكيدك. يمكنك تحديد الورقة وعمود الاسم وبداية صف البيانات.')}<div class="action-strip"><button class="btn primary" data-action="select-import">⇧ اختيار ملف Excel أو CSV</button></div></div>`;const sheet=importSheets[selectedImport],cols=Math.min(25,Math.max(2,...sheet.rows.slice(0,10).map(r=>r.length))),data=previewNames(sheet,importCol,importRow),existing=new Set(studentsFor(db,active).map(s=>normalizedName(s.name))),newNames=data.names.filter(x=>!existing.has(normalizedName(x)));return `<div class="page-head"><div><h2>معاينة ملف الاستيراد</h2><p class="hint">اختر الاسم الصحيح قبل الإضافة. لا توجد أي عملية تعديل على ملف Excel الأصلي.</p></div><button class="btn" data-action="clear-import">ملف آخر</button></div><div class="panel"><div class="fields"><label class="field"><span>ورقة العمل</span><select id="importSheet">${importSheets.map((x,i)=>`<option value="${i}" ${i===selectedImport?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>عمود أسماء الطلبة</span><select id="importColumn">${Array.from({length:cols},(_,i)=>`<option value="${i}" ${i===importCol?'selected':''}>${excelColumn(i)} — ${esc(sheet.rows.slice(0,2).map(r=>r[i]||'').filter(Boolean).join(' / ').slice(0,35)||'فارغ')}</option>`).join('')}</select></label><label class="field"><span>أول صف يحتوي أسماء (1-based)</span><input id="importStart" type="number" min="1" max="25000" value="${importRow}"></label></div><div class="grid cols3" style="margin:18px 0">${metric('أسماء صالحة',data.names.length,'♙')}${metric('جديدة',newNames.length,'＋')}${metric('مكررة أو موجودة',data.duplicates.length+data.names.length-newNames.length,'≋')}</div><h3>معاينة الأسماء الجديدة</h3>${newNames.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>التسلسل</th><th>الاسم الذي سيُضاف</th></tr></thead><tbody>${newNames.slice(0,30).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x)}</td></tr>`).join('')}</tbody></table></div><div class="hint">${newNames.length>30?'عرض أول 30 اسماً في المعاينة؛ البقية ستُستورد.':''}</div>`:empty('لا توجد أسماء جديدة')}</div><div class="action-strip"><button class="btn primary" data-action="confirm-import" ${!newNames.length?'disabled':''}>استيراد ${newNames.length} طالباً إلى ${esc(cls().name)}</button><button class="btn" data-nav="students">إلغاء</button></div>`;}
function normalizedName(s){return String(s||'').normalize('NFKC').replace(/\s+/g,' ').trim().toLocaleLowerCase()}
function addStudent(name){name=String(name||'').replace(/\s+/g,' ').trim();if(!name||name.length>180)throw Error('أدخل اسماً صالحاً لا يتجاوز 180 حرفاً');if(studentsFor(db,active).some(s=>normalizedName(s.name)===normalizedName(name)))throw Error('هذا الاسم موجود في الشعبة بالفعل');db.students.push({id:ID(),classId:active,name});persist()}
function exportFile(content,name,type){if(globalThis.AndroidBridge?.saveBase64){const reader=new FileReader();reader.onload=()=>AndroidBridge.saveBase64(name,type,String(reader.result).split(',')[1]||'');reader.readAsDataURL(new Blob([content],{type}));return;}const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function csvVal(v){let s=String(v??'');if(/^[\s]*[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportGrades(){
 const c=cls(),ev=db.assessments.filter(e=>e.classId===active),cfg=C(),periods=cfg.periods,stages=cfg.stages||[];
 const header=['الطالب',...ev.map(e=>`${cfg.periods.find(p=>p.id===e.periodId)?.name||''}: ${e.title} (من ${e.max})`)];
 for(const p of periods){for(const cat of cfg.categories)header.push(`${p.name}: ${cat.name} (من ${cat.max})`);
  for(const group of ['activity','monthly']){let cats=cfg.categories.filter(x=>x.group===group);if(cats.length)header.push(`${p.name}: ${group==='activity'?'مجموع النشاط':'مجموع الشهري'} (من ${cats.reduce((a,x)=>a+(+x.max),0)})`)}
  header.push(`${p.name}: النتيجة من ${cfg.scale}`,`${p.name}: غياب`);
 }
 header.push('معدل الفترات');
 for(const st of stages){for(const part of st.components)header.push(`${st.name}: ${part.name} (من ${part.max})`);header.push(`${st.name}: المجموع (من ${st.scale})`)}
 for(const a of cfg.annual.filter(x=>x.source==='manual'))header.push(a.name);
 header.push('النتيجة السنوية حسب المعادلة المحددة','إجمالي الغياب');
 const rows=[header];
 for(const student of studentsFor(db,active)){
  const row=[student.name,...ev.map(e=>db.marks[e.id]?.[student.id]??'')];
  for(const p of periods){for(const cat of cfg.categories)row.push(categoryScore(db,c,student.id,p.id,cat).value??'');
   for(const group of ['activity','monthly'])if(cfg.categories.some(x=>x.group===group))row.push(groupScore(db,c,student.id,p.id,group).value??'');
   row.push(periodScore(db,c,student.id,p.id).value??'',attendanceStats(db,student.id,p.id).absent);
  }
  row.push(termScore(db,c,student.id)??'');
  for(const st of stages){for(const part of st.components)row.push(db.stageMarks?.[student.id]?.[st.id]?.[part.id]??'');row.push(stageScore(db,c,student.id,st.id).value??'')}
  for(const a of cfg.annual.filter(x=>x.source==='manual'))row.push(db.manual[student.id]?.[a.id]??'');
  row.push(annualScore(db,c,student.id)??'',periods.reduce((sum,p)=>sum+attendanceStats(db,student.id,p.id).absent,0));
  rows.push(row);
 }
 exportFile('\ufeff'+rows.map(r=>r.map(csvVal).join(',')).join('\r\n'),'إعداد-كشف-النتائج-'+now()+'.csv','text/csv;charset=utf-8');
 toast(`تم تصدير ${studentsFor(db,active).length} سجل، مع الأعمدة المترابطة لجميع الفترات`);
}
function exportBackup(){exportFile(JSON.stringify(db,null,2),'إعداد-نسخة-احتياطية-'+now()+'.json','application/json;charset=utf-8');toast('تم إنشاء نسخة احتياطية شاملة')}
