// IDAD 9.2: Native Android page scroll. Buttons only appear on genuinely long pages.
(function setupPageJump(){
 const panel=document.getElementById('pageJump');
 const up=document.getElementById('pageJumpTop');
 const down=document.getElementById('pageJumpBottom');
 if(!panel||!up||!down)return;
 let scheduled=false;
 const update=()=>{
  scheduled=false;
  const root=document.scrollingElement||document.documentElement;
  const max=Math.max(0,root.scrollHeight-window.innerHeight);
  const pos=window.scrollY||root.scrollTop||0;
  panel.classList.toggle('visible',window.matchMedia('(max-width:810px)').matches && max>window.innerHeight*.65);
  up.disabled=pos<30;
  down.disabled=pos>=max-30;
 };
 const schedule=()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update)}};
 up.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));
 down.addEventListener('click',()=>window.scrollTo({top:document.scrollingElement?.scrollHeight||document.documentElement.scrollHeight,behavior:'smooth'}));
 window.addEventListener('scroll',schedule,{passive:true});
 window.addEventListener('resize',schedule,{passive:true});
 // Since only #content is replaced on route changes, observe its child changes (not its full subtree).
 new MutationObserver(schedule).observe(document.getElementById('content'),{childList:true});
 schedule();
})();
