// Account gate. No teacher information can render until auth and cloud load succeed.
function showGate(msg='',errorMessage=false){
 document.body.classList.add('locked');
 $('authGate').hidden=false;
 const out=$('authMessage');out.textContent=msg;out.className=errorMessage?'auth-feedback error':'auth-feedback';
}
function unlockGate(){document.body.classList.remove('locked');$('authGate').hidden=true;}
async function enterAccount(){
 showGate('جارٍ تحميل مساحتك الخاصة...');
 const space=await cloud.getWorkspace(newSchool());
 const data=normalizeImportedDb(space.payload);
 // Switch the account in one step only after successful authorization and load.
 accountGeneration++;db=data;authenticated=true;cloudRevision=Number(space.revision);cloudDirty=false;cloudBusy=false;cloudBlocked=false;
 active=db.settings?.activeClass||db.classes[0]?.id||null;
 if(!db.classes.some(c=>c.id===active))active=db.classes[0]?.id||null;
 route=active?'dashboard':'welcome';periodId=null;assessmentId=null;configDraft=null;
 for(const key in pageState)pageState[key]=0;
 $('accountEmail').textContent=cloud.user.email||'حساب المدرس';
 setCloudBanner();document.body.classList.remove('cloud-paused');status('محفوظ سحابياً','ok');unlockGate();render();
}
async function reloadFromCloud(){
 if(cloudBusy){toast('انتظر انتهاء عملية الحفظ','error');return;}
 showGate('جارٍ تحميل أحدث نسخة محفوظة...');
 try{const space=await cloud.getWorkspace(newSchool());const data=normalizeImportedDb(space.payload);
  accountGeneration++;db=data;cloudRevision=Number(space.revision);cloudBlocked=false;cloudDirty=false;clearTimeout(cloudTimer);
  active=db.settings?.activeClass||db.classes[0]?.id||null;route=active?'dashboard':'welcome';periodId=null;assessmentId=null;configDraft=null;
  setCloudBanner();document.body.classList.remove('cloud-paused');status('محفوظ سحابياً','ok');unlockGate();render();
 }catch(e){showGate(e.message,true);}
}
async function signOut(){
 if(cloudBusy||cloudDirty){
  await syncNow();
  if(cloudBusy||cloudDirty){toast('لا يمكن الخروج قبل حفظ التغييرات. نزّل نسخة JSON ثم حاول مجدداً.','error');return;}
 }
 showGate('جارٍ تسجيل الخروج...');accountGeneration++;authenticated=false;document.body.classList.remove('cloud-paused');
 clearTimeout(cloudTimer);cloudTimer=null;db=newSchool();active=null;route='welcome';cloudDirty=false;cloudBusy=false;cloudBlocked=false;cloudRevision=0;
 await cloud.logout();$('accountEmail').textContent='';status('غير متصل');showGate('تم تسجيل الخروج بأمان.');
}
$('cloudSignOut').addEventListener('click',()=>{void signOut()});
