$('authToggle').addEventListener('click',()=>{
 const form=$('authForm'),newUser=form.dataset.mode!=='signup';form.dataset.mode=newUser?'signup':'login';
 $('authSubmit').textContent=newUser?'إنشاء حساب المدرس':'تسجيل الدخول';
 $('authToggle').textContent=newUser?'لديك حساب؟ سجّل الدخول':'ليس لديك حساب؟ أنشئ حساباً';
 $('authMessage').textContent='';
});
$('authForm').addEventListener('submit',async event=>{
 event.preventDefault();
 if(!cloud.configured)return showGate('أكمل إعداد مشروع Supabase أولاً في ملف cloud-config.js.',true);
 const form=event.currentTarget;
 const email=String(form.elements.email.value||'').trim().toLowerCase();
 const pass=String(form.elements.password.value||'');
 const remember=!!form.elements.remember.checked;
 if(pass.length<8)return showGate('استخدم كلمة مرور لا تقل عن 8 أحرف.',true);
 $('authSubmit').disabled=true;showGate('جارٍ التحقق من الحساب...');
 try{
  if(form.dataset.mode==='signup'){
   const data=await cloud.signup(email,pass,remember);
   if(!data?.access_token){showGate('تم إرسال رسالة تأكيد إلى بريدك. افتح الرابط ثم عُد إلى التطبيق.');return;}
  }else await cloud.login(email,pass,remember);
  await enterAccount();
 }catch(e){showGate('تعذر تسجيل الدخول: '+e.message,true)}
 finally{$('authSubmit').disabled=false;}
});
$('authForgot').addEventListener('click',async()=>{
 const email=$('authEmail').value.trim();if(!email)return showGate('اكتب بريدك الإلكتروني أولاً.');
 try{
  await cloud.call('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',data:{email}});
  showGate('إذا كان البريد مسجلاً، ستصلك رسالة لإعادة تعيين كلمة المرور.');
 }catch(e){showGate(e.message,true)}
});
$('authChangePassword').addEventListener('click',async()=>{
 const pass=$('resetPassword').value;
 if(pass.length<8)return showGate('كلمة المرور الجديدة يجب أن تكون 8 أحرف على الأقل',true);
 try{
  await cloud.call('/auth/v1/user',{method:'PUT',auth:true,data:{password:pass}});
  $('passwordReset').hidden=true;await enterAccount();
 }catch(e){showGate(e.message,true)}
});
async function start(){
 if(!cloud.configured){showGate('النسخة معدّة للاستخدام المتعدد لكنها لم تُربط بمشروع Supabase بعد. على مسؤول التطبيق ضبط URL وPublishable Key في cloud-config.js.',true);$('authSubmit').disabled=true;return;}
 showGate('جارٍ التحقق من تسجيل الدخول...');
 const wasRecovery=location.hash.includes('type=recovery');
 const result=await cloud.restore();
 if(result.authenticated){
  if(wasRecovery){$('passwordReset').hidden=false;showGate('اختر كلمة مرور جديدة ثم احفظها.');return;}
  try{await enterAccount()}catch(e){showGate('تعذر تحميل البيانات: '+e.message,true)}
 }else showGate(result.message||'سجّل دخولك للوصول إلى بياناتك الخاصة.',!!result.message);
}
